व्यवसायात्मिका बुद्धिः समाधौ न विधीयते ॥ ४४ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":774,\"bb\":697,\"url_path\":\"/en/library/bg/2/44/b697/\",\"body_value\":\"bhogaiśvarya-prasaktānāṁ
tayāpahṛta-cetasām
vyavasāyātmikā buddhiḥ
samādhau na vidhīyate\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":775,\"bb\":698,\"url_path\":\"/en/library/bg/2/44/b698/\",\"shadow_value\":\"bhoga – to material enjoyment; aiśvarya – and opulence; prasaktānām – for those who are attached; tayā – by such things; apahṛta-cetasām – bewildered in mind; vyavasāya-ātmikā – fixed in determination; buddhiḥ – devotional service to the Lord; samādhau – in the controlled mind; na – never; vidhīyate – does take place.\",\"word_for_word_value\":[{\"word\":\"bhoga\",\"translation\":\"to material enjoyment\"},{\"word\":\"aiśvarya\",\"translation\":\"and opulence\"},{\"word\":\"prasaktānām\",\"translation\":\"for those who are attached\"},{\"word\":\"tayā\",\"translation\":\"by such things\"},{\"word\":\"apahṛta-cetasām\",\"translation\":\"bewildered in mind\"},{\"word\":\"vyavasāya-ātmikā\",\"translation\":\"fixed in determination\"},{\"word\":\"buddhiḥ\",\"translation\":\"devotional service to the Lord\"},{\"word\":\"samādhau\",\"translation\":\"in the controlled mind\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"vidhīyate\",\"translation\":\"does take place\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":776,\"bb\":699,\"url_path\":\"/en/library/bg/2/44/b699/\",\"body_value\":\"In the minds of those who are too attached to sense enjoyment and material opulence, and who are bewildered by such things, the resolute determination for devotional service to the Supreme Lord does not take place.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":777,\"bb\":700,\"url_path\":\"/en/library/bg/2/44/b700/\",\"body_value\":\"Samādhi means “fixed mind.” The Vedic dictionary, the Nirukti, says, samyag ādhīyate ’sminn ātma-tattva-yāthātmyam: “When the mind is fixed for understanding the self, it is said to be in samādhi.” Samādhi is never possible for persons interested in material sense enjoyment and bewildered by such temporary things. They are more or less condemned by the process of material energy.\"}]}],\"short_title\":\"Bg. 2.44\",\"medium_title\":\"Bhagavad-gītā As It Is 2.44\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/\",\"className\":\"text-vb-link\",\"children\":\"Library\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",null,{\"href\":\"/en/library/bg/\",\"className\":\"text-vb-link\",\"children\":\"Bhagavad-gītā As It Is\"}],\" » \"]}],[\"$\",\"li\",\"/en/library/bg/2/\",{\"className\":\"inl