\",\"title\":\"TEXT 44\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/2/46/\",\"title\":\"TEXT 46\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":779,\"bb\":567968,\"url_path\":\"/en/library/bg/2/45/devanagari/\",\"body_final\":\"त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन ।
निर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् ॥ ४५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":780,\"bb\":702,\"url_path\":\"/en/library/bg/2/45/b702/\",\"body_value\":\"trai-guṇya-viṣayā vedā
nistrai-guṇyo bhavārjuna
nirdvandvo nitya-sattva-stho
niryoga-kṣema ātmavān\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":781,\"bb\":703,\"url_path\":\"/en/library/bg/2/45/b703/\",\"shadow_value\":\"trai-guṇya – pertaining to the three modes of material nature; viṣayāḥ – on the subject matter; vedāḥ – Vedic literatures; nistrai-guṇyaḥ – transcendental to the three modes of material nature; bhava – be; arjuna – O Arjuna; nirdvandvaḥ – without duality; nitya-sattva-sthaḥ – in a pure state of spiritual existence; niryoga-kṣemaḥ – free from ideas of gain and protection; ātma-vān – established in the self.\",\"word_for_word_value\":[{\"word\":\"trai-guṇya\",\"translation\":\"pertaining to the three modes of material nature\"},{\"word\":\"viṣayāḥ\",\"translation\":\"on the subject matter\"},{\"word\":\"vedāḥ\",\"translation\":\"Vedic literatures\"},{\"word\":\"nistrai-guṇyaḥ\",\"translation\":\"transcendental to the three modes of material nature\"},{\"word\":\"bhava\",\"translation\":\"be\"},{\"word\":\"arjuna\",\"translation\":\"O Arjuna\"},{\"word\":\"nirdvandvaḥ\",\"translation\":\"without duality\"},{\"word\":\"nitya-sattva-sthaḥ\",\"translation\":\"in a pure state of spiritual existence\"},{\"word\":\"niryoga-kṣemaḥ\",\"translation\":\"free from ideas of gain and protection\"},{\"word\":\"ātma-vān\",\"translation\":\"established in the self\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":782,\"bb\":704,\"url_path\":\"/en/library/bg/2/45/b704/\",\"body_value\":\"The Vedas deal mainly with the subject of the three modes of material nature. O Arjuna, become transcendental to these three modes. Be free from all dualities and from all anxieties for gain and safety, and be established in the self.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":783,\"bb\":705,\"url_path\":\"/en/library/bg/2/45/b705/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":784,\"bb\":706,\"url_path\":\"/en/library/bg/2/45/b706/\",\"body_value\":\"As long as the material body exists, there are actions and reactions in the material modes. One has to learn tolerance in the face of dualities such as happiness and distress, or cold and warmth, and by tolerating such dualities become free from anxieties regarding gain and loss. This transcendental position is achieved in full Kṛṣṇa consciousness when one is fully dependent on the good will of Kṛṣṇa.\"}]}],\"short_title\":\"Bg. 2.45\",\"medium_title\":\"Bhagavad-gītā As It Is 2.45\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n26:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",nu