sName\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"in all respects\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-4\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-sampluta\",{\"href\":\"/en/search/synonyms/?original=sampluta\",\"children\":[\"$\",\"em\",null,{\"children\":\"sampluta\"}]}],\"-\",[\"$\",\"$L20\",\"wfwundefined-2-udake\",{\"href\":\"/en/search/synonyms/?original=udake\",\"children\":[\"$\",\"em\",null,{\"children\":\"udake\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"in a great reservoir of water\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-5\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-tāvān\",{\"href\":\"/en/search/synonyms/?original=tāvān\",\"children\":[\"$\",\"em\",null,{\"children\":\"tāvān\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"similarly\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-6\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-sarveṣu\",{\"href\":\"/en/search/synonyms/?original=sarveṣu\",\"children\":[\"$\",\"em\",null,{\"children\":\"sarveṣu\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"in all\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-7\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vedeṣu\",{\"href\":\"/en/search/synonyms/?original=vedeṣu\",\"children\":[\"$\",\"em\",null,{\"children\":\"vedeṣu\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"Vedic literatures\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-8\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-brāhmaṇasya\",{\"href\":\"/en/search/synonyms/?original=brāhmaṇasya\",\"children\":[\"$\",\"em\",null,{\"children\":\"brāhmaṇasya\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"of the man who knows the Supreme Brahman\"}}],\"; \"]}],[\"$\",\"span\",\"wfwundefined-9\",{\"className\":\"inline\",\"children\":[[[\"$\",\"$L20\",\"wfwundefined-0-vijānataḥ\",{\"href\":\"/en/search/synonyms/?original=vijānataḥ\",\"children\":[\"$\",\"em\",null,{\"children\":\"vijānataḥ\"}]}]],\" — \",[\"$\",\"span\",null,{\"className\":\"inline\",\"dangerouslySetInnerHTML\":{\"__html\":\"who is in complete knowledge\"}}],\".\"]}]]}]}]]]}]\n"])self.__next_f.push([1,"2e:[\"$\",\"div\",\"785-translation,785-translation\",{\"className\":\"av-translation\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Translation\"}],[[\"$\",\"$L2a\",\"child-789\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:3:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"$\",\"strong\",null,{\"dangerouslySetInnerHTML\":{\"__html\":\"All purposes served by a small well can at once be served by a great reservoir of water. Similarly, all the purposes of the Vedas can be served to one who knows the purpose behind them.\"}}]}]}]]]}]\n32:T684,"])self.__next_f.push([1,"So one must be intelligent enough to understand the purpose of the Vedas, without being attached to the rituals only, and must not desire to be elevated to the heavenly kingdoms for a better quality of sense gratification. It is not possible for the common man in this age to follow all the rules and regulations of the Vedic rituals, nor is it possible to study all of the Vedānta and the Upaniṣads thoroughly. It requires much time, energy, knowledge and resources to execute the purposes of the Vedas. This is hardly possible in this age. The best purpose of Vedic culture is served, however, by chanting the holy name of the Lord, as recommended by Lord Caitanya, the deliverer of all fallen souls. When Lord Caitanya was asked by a great Vedic scholar, Prakāśānanda Sarasvatī, why He, the Lord, was chanting the holy name of the Lord like a sentimentalist instead of studying Vedānta philosophy, the Lord replied that His spiritual master had found Him to be a great fool and thus asked Him to chant the holy name of Lord Kṛṣṇa. He did so, and became ecstatic like a madman. In this Age of Kali, most of the population is foolish and not adequately educated to understand Vedānta philosophy; the best purpose of Vedānta philosophy is served by inoffensively chanting the holy name of the Lord. Vedānta is the last word in Vedic wisdom, and the author and knower of the Vedānta philosophy is Lord Kṛṣṇa; and the highest Vedāntist is the great soul who takes pleasure in chanting the holy name of the Lord. That is the ultimate purpose of all Vedic mysticism."])self.__next_f.push([1,"2f:[\"$\",\"div\",\"785-purport,785-purport\",{\"className\":\"av-purport\",\"children\":[[\"$\",\"h2\",null,{\"className\":\"text-center em-leading-5 em-text-xl font-bold em-mb-4\",\"children\":\"Purport\"}],[[\"$\",\"$L2a\",\"child-790\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:0\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"children\":[\"The rituals and sacrifices mentioned in the \",[\"$\",\"em\",\"1\",{\"children\":\"karma-kāṇḍa\"}],\" division of the Vedic literature are meant to encourage gradual development of self-realization. And the purpose of self-realization is clearly stated in the Fifteenth Chapter of the \",[\"$\",\"$L20\",\"3\",{\"href\":\"/en/library/bg/15/15/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhagavad-gītā\"}],\" (15.15)\"]}],\": the purpose of studying the \",[\"$\",\"em\",\"5\",{\"children\":\"Vedas\"}],\" is to know Lord Kṛṣṇa, the primeval cause of everything. So, self-realization means understanding Kṛṣṇa and one’s eternal relationship with Him. The relationship of the living entities with Kṛṣṇa is also mentioned in the Fifteenth Chapter of \",[\"$\",\"$L20\",\"7\",{\"href\":\"/en/library/bg/15/7/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Bhagavad-gītā\"}],\" (15.7)\"]}],\". The living entities are parts and parcels of Kṛṣṇa; therefore, revival of Kṛṣṇa consciousness by the individual living entity is the highest perfectional stage of Vedic knowledge. This is confirmed in the \",[\"$\",\"$L20\",\"9\",{\"href\":\"/en/library/sb/3/33/7/\",\"children\":[[\"$\",\"em\",\"0\",{\"children\":\"Śrīmad-Bhāgavatam\"}],\" (3.33.7)\"]}],\" as follows:\"]}]}],[\"$\",\"$L2a\",\"child-791\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:1\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base text-center italic\",\"dangerouslySetInnerHTML\":{\"__html\":\"aho bata śva-paco ’to garīyān
yaj-jihvāgre vartate nāma tubhyam
tepus tapas te juhuvuḥ sasnur āryā
brahmānūcur nāma gṛṇanti ye te\"}}]}],[\"$\",\"$L2a\",\"child-792\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:2\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"“O my Lord, a person who is chanting Your holy name, although born of a low family like that of a caṇḍāla [dog-eater], is situated on the highest platform of self-realization. Such a person must have performed all kinds of penances and sacrifices according to Vedic rituals and studied the Vedic literatures many, many times after taking his bath in all the holy places of pilgrimage. Such a person is considered to be the best of the Āryan family.”\"}}]}],[\"$\",\"$L2a\",\"child-793\",{\"child\":\"$23:props:children:0:props:children:props:page:child_items:4:children:3\",\"hasId\":true,\"children\":[\"$\",\"div\",null,{\"className\":\"em-mb-4 em-leading-8 em-text-base s-justify\",\"dangerouslySetInnerHTML\":{\"__html\":\"$32\"}}]}]]]}]\n"])self.__next_f.push([1,"33:[[\"$\",\"source\",null,{\"srcSet\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"media\":\"(prefers-color-scheme: dark)\"}],[\"$\",\"img\",null,{\"src\":\"https://simpleanalyticsbadges.com/vedabase.io?mode=auto\",\"loading\":\"lazy\",\"referrerPolicy\":\"no-referrer\",\"crossOrigin\":\"anonymous\"}]]\n"])self.__next_f.push([1,"27:[\"$\",\"div\",null,{\"id\":\"footer\",\"className\":\"mt-auto w-full max-w-7xl mx-auto pt-3 mb-6 text-sm text-vb-normal-text/80 text-center\",\"children\":[[\"$\",\"$L1f\",null,{\"donors\":\"Shweta Saxena; Gopalakrishnan Soundarajan;    Kuldip Persaud;  Raghava Chandra Dasa; Shubhangi Rajiv Panjiyar; Suparna Kotaru;  Rajendra and Geeta Ramchandani;  Jaykumar Prabhakar; Bharat Vyas; Shri Chander Mohan Gilhotra, HG Prashant Mukund Das, Shri Trilok Singh Grover, HG Bhakta Mitra Das, Laxmi Narayan Agarwal; Ronak Talati; Bhargav Ashok; Akiralali; Rajasa das; Riya and T